const MODEL = 'google/gemini-2.5-flash-lite';

const today = new Date();
const todayStr = today.toISOString().split('T')[0];

const PROMPT = `You are FridgeMate AI, an expert OCR & Receipt Analyzer. Today's date is ${todayStr}.
Analyze the uploaded image (either a food product expiry label or a grocery store purchase receipt).
Identify all items and their expiry dates, then respond with ONLY valid JSON in this exact structure, no markdown, no explanation:

{
  "items": [
    {
      "name": "<Food/Product name in Thai>",
      "category": "Meat|Vegetable|Egg|Dairy|Cooked Food|Fruit|Other",
      "quantity": <number>,
      "unit": "<unit e.g. แพ็ค/ขวด/ฟอง/ชิ้น/กิโล/ถุง>",
      "expiry_date": "YYYY-MM-DD"
    }
  ]
}

Guidelines:
1. Product Expiry Label Scan:
   - Locate any expiration label text (e.g. EXP, BB, BBE, Best Before, หมดอายุ) and extract the expiration date.
   - Convert the date to YYYY-MM-DD format.
2. Grocery Receipt Scan:
   - Extract all food/grocery items purchased, including their quantities and units.
   - For each item, estimate a safe expiry date based on standard shelf life from today's date (${todayStr}):
     - Meat (เนื้อสัตว์): 3 days from now
     - Vegetable (ผัก): 4 days from now
     - Dairy (นม/เนย/ชีส): 7 days from now
     - Egg (ไข่): 14 days from now
     - Cooked Food (อาหารปรุงสำเร็จ): 3 days from now
     - Fruit (ผลไม้): 6 days from now
     - Other (อื่นๆ): 14 days from now
   - Set the calculated date in "expiry_date".

Respond ONLY with valid JSON. Do not include markdown code fences.`;

const item = $input.first();
const binaryKeys = Object.keys(item.binary || {});
const binaryKey = binaryKeys.includes('photo') ? 'photo' : (binaryKeys[0] || 'photo');
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const mime = item.binary?.[binaryKey]?.mimeType || 'image/jpeg';
const dataUrl = `data:${mime};base64,${buffer.toString('base64')}`;

return [{
  json: {
    body: {
      model: MODEL,
      messages: [
        {
          role: 'user',
          content: [
            { type: 'text', text: PROMPT },
            { type: 'image_url', image_url: { url: dataUrl } }
          ]
        }
      ]
    }
  }
}];

const raw = $input.first().json;

let text = raw.choices?.[0]?.message?.content
  ?? raw.content ?? raw.text ?? raw.output ?? raw.response ?? '';
if (typeof text !== 'string') {
  text = JSON.stringify(text);
}

if (!text && raw.error) {
  return [{ json: {
    items: [],
    error: true,
    note_th: 'AI ขัดข้อง: ' + (raw.error.message || 'unknown error')
  } }];
}

let cleaned = text.trim()
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/```\s*$/, '')
  .trim();

let parsed = null;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); } catch (e2) {}
  }
}

if (!parsed || typeof parsed !== 'object') {
  parsed = {
    items: [],
    error: true,
    note_th: 'ไม่สามารถอ่านผลวิเคราะห์จาก AI ได้'
  };
}

return [{ json: parsed }];

const payload = $input.first().json;
const hh = payload.household_id || 'HOME123';
const count = payload.expiring_count || 0;
const itemsList = payload.items || [];

const listText = itemsList.map(i => `- ${i.name} (${i.quantity} ${i.unit}) เหลือ ${i.days_left} วัน`).join('\n');

const message = `\n[เตือนตู้เย็นส่วนรวม - บ้าน ${hh}]\nมีวัตถุดิบใกล้หมดอายุ ${count} รายการ:\n${listText}`;

return [{ json: { message } }];
